function clean(value) {
  return String(value || "").trim();
}

function lower(value) {
  return clean(value).toLowerCase();
}

function getTodayJakarta() {
  const now = new Date();
  const jakartaDate = now.toLocaleDateString("en-CA", {
    timeZone: "Asia/Jakarta"
  });
  return new Date(jakartaDate + "T00:00:00+07:00");
}

function formatDate(date) {
  return date.toISOString().slice(0, 10);
}

function addMonths(date, months) {
  const result = new Date(date);
  result.setMonth(result.getMonth() + months);
  return result;
}

const input = $("Edit Fields - Normalisasi Input").first().json;

const dataKaryawan = $items("Ambil Master Karyawan")
  .map(item => item.json)
  .filter(row => clean(row.NIK));

const aturanPelanggaran = $items("Ambil Aturan SP")
  .map(item => item.json)
  .filter(row => clean(row.Jenis_Pelanggaran));

const riwayatSP = $items("Ambil Riwayat SP")
  .map(item => item.json)
  .filter(row => clean(row.NIK));

const nik = clean(input.NIK);
const jenisPelanggaran = clean(input.Jenis_Pelanggaran);

function error(message) {
  return [{
    json: {
      valid: false,
      error_message: message,
      ID_Pengajuan: input.ID_Pengajuan,
      NIK: nik,
      Nama_HR: input.Nama_HR,
      Email_HR: input.Email_HR
    }
  }];
}

if (!nik) {
  return error("NIK tidak boleh kosong.");
}

if (!jenisPelanggaran) {
  return error("Jenis pelanggaran tidak boleh kosong.");
}

if (!clean(input.Tanggal_Kejadian)) {
  return error("Tanggal kejadian tidak boleh kosong.");
}

if (!clean(input.Deskripsi_Kejadian)) {
  return error("Deskripsi kejadian tidak boleh kosong.");
}

const karyawan = dataKaryawan.find(row => clean(row.NIK) === nik);

if (!karyawan) {
  return error("NIK karyawan tidak ditemukan di sheet Data_Karyawan.");
}

if (lower(karyawan.Status_Karyawan) !== "aktif") {
  return error("Karyawan tidak berstatus aktif.");
}

if (!clean(karyawan.Email_Karyawan)) {
  return error("Email karyawan kosong di sheet Data_Karyawan.");
}

const aturan = aturanPelanggaran.find(row => {
  return lower(row.Jenis_Pelanggaran) === lower(jenisPelanggaran);
});

if (!aturan) {
  return error("Jenis pelanggaran belum tersedia di sheet Aturan Pelanggaran.");
}

const kategori = lower(aturan.Kategori);

if (!["ringan", "sedang", "berat"].includes(kategori)) {
  return error("Kategori pelanggaran harus Ringan, Sedang, atau Berat.");
}

const riwayatAktif = riwayatSP.filter(row => {
  const sameNik = clean(row.NIK) === nik;
  const statusSP = lower(row.Status_SP || "AKTIF");
  return sameNik && statusSP !== "dibatalkan";
});

const jumlahPelanggaranSebelumnya = riwayatAktif.length;
const pelanggaranKe = jumlahPelanggaranSebelumnya + 1;

let tingkatSPNumber = 1;

if (kategori === "berat" || pelanggaranKe >= 3) {
  tingkatSPNumber = 3;
} else if (kategori === "sedang" || pelanggaranKe >= 2) {
  tingkatSPNumber = 2;
} else {
  tingkatSPNumber = 1;
}

const tingkatSP = "SP" + tingkatSPNumber;

const today = getTodayJakarta();
const masaBerlakuBulan = Number(aturan.Masa_Berlaku_Bulan || 6);
const tanggalBerlakuSampai = addMonths(today, masaBerlakuBulan);

const noSP =
  "SP-" +
  today.getFullYear() +
  "-" +
  nik +
  "-" +
  Date.now().toString().slice(-6);

return [{
  json: {
    valid: true,

    ID_Pengajuan: input.ID_Pengajuan,
    No_SP: noSP,

    Tanggal_SP: formatDate(today),
    Tanggal_Berlaku_Sampai: formatDate(tanggalBerlakuSampai),

    NIK: nik,
    Nama_Karyawan: karyawan.Nama_Karyawan,
    Email_Karyawan: karyawan.Email_Karyawan,
    Jabatan: karyawan.Jabatan,
    Departemen: karyawan.Departemen,

    Jenis_Pelanggaran: jenisPelanggaran,
    Kategori: aturan.Kategori,
    Tingkat_SP: tingkatSP,
    Pelanggaran_Ke: pelanggaranKe,

    Dasar_Aturan_Internal: aturan.Dasar_Aturan_Internal,
    Perbaikan_Diharapkan: aturan.Perbaikan_Diharapkan,

    Tanggal_Kejadian: input.Tanggal_Kejadian,
    Deskripsi_Kejadian: input.Deskripsi_Kejadian,
    Bukti_URL: input.Bukti_URL,

    Nama_HR: input.Nama_HR,
    Email_HR: input.Email_HR,

    Jumlah_Pelanggaran_Sebelumnya: jumlahPelanggaranSebelumnya
  }
}];

const item = $input.first();

const binaryKeys = Object.keys(item.binary || {});

if (binaryKeys.length === 0) {
  throw new Error('Tidak ada binary file dari node Convert HTML to PDF.');
}

const sourceKey = binaryKeys.includes('data') ? 'data' : binaryKeys[0];

const buffer = await this.helpers.getBinaryDataBuffer(0, sourceKey);

const header = buffer.subarray(0, 4).toString('utf8');

if (header !== '%PDF') {
  const preview = buffer.subarray(0, 120).toString('utf8');
  const mime = item.binary[sourceKey]?.mimeType || '-';
  const size = buffer.length;

  throw new Error(
    `File bukan PDF valid. Header: ${header}, Mime: ${mime}, Size: ${size} bytes, Preview: ${preview}`
  );
}

const sp = $('Tentukan SP').first().json;

const safeName = String(sp.Nama_Karyawan || 'Karyawan')
  .replace(/[^a-zA-Z0-9-_ ]/g, '')
  .replace(/\s+/g, '_');

const fileName = `Surat_Peringatan_${sp.Tingkat_SP || 'SP'}_${safeName}.pdf`;

item.binary = {
  data: await this.helpers.prepareBinaryData(buffer, fileName, 'application/pdf')
};

return [item];
